const API_BASE_URL = (
  process.env.REACT_APP_API_BASE_URL
  || process.env.REACT_APP_BACKEND_API
  || 'https://filiya-backend.onrender.com/api'
).replace(/\/+$/, '');

export const GOOGLE_LOGIN_URL = `${API_BASE_URL}/auth/google/login`;

// Token storage (in memory for security)
let authToken = null;

export const setAuthToken = (token) => {
  authToken = token;
};

export const clearAuthToken = () => {
  authToken = null;
};

export const apiRequest = async (endpoint, options = {}) => {
  const defaultHeaders = {
    'Content-Type': 'application/json',
  };

  // Add Authorization header if token is available
  if (authToken) {
    defaultHeaders['Authorization'] = `Bearer ${authToken}`;
  }

  const defaultOptions = {
    credentials: 'include',
    headers: {
      ...defaultHeaders,
      ...options.headers,
    },
  };

  const response = await fetch(`${API_BASE_URL}${endpoint}`, {
    ...defaultOptions,
    ...options,
    headers: {
      ...defaultOptions.headers,
      ...options.headers,
    },
  });

  const data = await response.json();

  // Handle errors in response (some endpoints return 200 with error field)
  if (data.error && data.error !== "") {
    throw data.error;
  }

  // Also throw on HTTP error status
  if (!response.ok) {
    throw data.error || `HTTP ${response.status}: ${response.statusText}`;
  }

  return data;
};

// Convenience methods
export const api = {
  get: (endpoint, options = {}) => 
    apiRequest(endpoint, { ...options, method: 'GET' }),

  post: (endpoint, body, options = {}) => 
    apiRequest(endpoint, { 
      ...options, 
      method: 'POST', 
      body: JSON.stringify(body) 
    }),

  put: (endpoint, body, options = {}) => 
    apiRequest(endpoint, { 
      ...options, 
      method: 'PUT', 
      body: JSON.stringify(body) 
    }),

  delete: (endpoint, options = {}) => 
    apiRequest(endpoint, { ...options, method: 'DELETE' }),
};
